<?php
if(!isset($documentType)){http_response_code(404);exit;}
require dirname(__DIR__).'/app/bootstrap.php';$perm=$documentType==='invoice'?'invoices':'quotations';require_permission($perm.'.create');require dirname(__DIR__).'/app/layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=create_document($documentType,$_POST,$_POST['items']??[]);flash(ucfirst($documentType).' draft saved. Review it before issuing.');redirect('invoice-view.php?id='.$id);}catch(DomainException $ex){$error=$ex->getMessage();}}
$customers=rows("SELECT id,name FROM customers WHERE business_id=? AND status='Active' ORDER BY name",[bid()]);$products=rows("SELECT id,name,price,tax_rate FROM products WHERE business_id=? AND status='Active' ORDER BY name",[bid()]);page_start('Create '.ucfirst($documentType),'Every detail adds up. Create a draft, then review and issue.','<a class="btn" href="'.$perm.'.php">'.icon('arrow-left').' Back to '.$perm.'</a>');error_notice($error);
?><form method="post" class="panel form-panel"><?php csrf_field(); ?><h2><?= ucfirst($documentType) ?> details</h2><p>Amounts are calculated and validated on the server.</p><div class="form-grid"><label class="field full"><span>Customer <b>*</b></span><select name="customer_id" required><option value="">Choose a customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= (string)($_POST['customer_id']??'')===(string)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><?php field('issue_date',['Document date','date',true],$_POST['issue_date']??date('Y-m-d'));field('due_date',[$documentType==='invoice'?'Due date':'Valid until','date',true],$_POST['due_date']??date('Y-m-d',strtotime('+30 days'))); ?></div><h3>Line items</h3><div id="invoice-items"></div><button class="btn small" type="button" data-add-item><?= icon('plus') ?> Add line item</button><div class="item-controls"><div class="invoice-live-total"><span>Estimated total</span><strong id="live-total">₹0.00</strong></div></div><?php field('notes',['Notes & payment terms','textarea'],$_POST['notes']??(profile()['terms']??'Thank you for your business.')); ?><div class="form-actions"><a class="btn" href="<?= $perm ?>.php">Cancel</a><button class="btn primary"><?= icon('device-floppy') ?> Save draft</button></div></form><template id="item-template"><div class="invoice-item-grid"><label class="field"><span>Product / description</span><select data-product data-field="product_id"><option value="">Custom item</option></select><input data-field="description" required placeholder="Item description" maxlength="500"></label><label class="field"><span>Quantity</span><input data-field="quantity" type="number" min="0.001" max="10000" step="0.001" value="1" required></label><label class="field"><span>Unit price (₹)</span><input data-field="rate" type="number" min="0" max="1000000" step="0.01" value="0" required></label><label class="field"><span>Discount %</span><input data-field="discount_rate" type="number" min="0" max="100" step="0.01" value="0"></label><label class="field"><span>Tax %</span><input data-field="tax_rate" type="number" min="0" max="100" step="0.01" value="0"></label><button class="icon-btn" type="button" data-remove-item aria-label="Remove line item"><?= icon('x') ?></button></div></template><script type="application/json" id="initial-items"><?= json_encode(array_slice(is_array($_POST['items']??null)?$_POST['items']:[],0,100),JSON_HEX_TAG|JSON_HEX_AMP) ?></script><script type="application/json" id="products-data"><?= json_encode($products,JSON_HEX_TAG|JSON_HEX_AMP) ?></script><?php page_end(); ?>
